    private PluginResult GetJavaVersions()
    {
        return new PluginResult(true);
    }

    private PluginResult InstallJava(string? version)
    {
        return new PluginResult(true);
    }

    private PluginResult UninstallJava(string? version)
    {
        return new PluginResult(true);
    }

    public override void RegisterServices(IServiceCollection services)
    {
        services.AddTransient<IPlugin, JavaPlugin>();
        services.AddTransient<JavaViewModel>();
        services.AddCommand(new JavaCommand(GlobalProvider.SystemContext));
        services.AddSingleton<ILocalizaitonResourceContributor, LocalizationResourceContributor>();
    }

    public override R? Execute<T, R>(string methodName, T? parameters)
        where T : default
        where R : class
    {
        return methodName switch
        {
            "GetJavaVersions" => GetJavaVersions() as R,
            "InstallJava" => InstallJava(parameters as string) as R,
            "UninstallJava" => UninstallJava(parameters as string) as R,
            _ => throw new Exception("插件方法不存在")
        };
    }
}
